/**
 * Offline once loaded.
 *
 * The deck is ~500 KB of static content and the schedule lives in `localStorage`, so there is
 * nothing here the network is needed for once the app has been opened. What is needed is that
 * the shell and its chunks are still there in a tunnel, on a plane, or when the signal drops
 * mid-session.
 *
 * ## Runtime caching, not a precache manifest
 *
 * The obvious build-time approach is to list every asset at build time and cache them on
 * install. Next.js emits content-hashed chunk names, so that list has to be generated by the
 * build and kept in step with it — a second source of truth that goes stale silently, and the
 * symptom is a white screen offline rather than an error anyone sees.
 *
 * Instead: cache what is actually fetched, and serve it when the network cannot be reached.
 * "Offline once loaded" is precisely what that gives, and precisely what was asked for. The
 * cost is that a *cold* first load still needs a network, which is unavoidable anyway.
 *
 * ## What is deliberately never cached
 *
 * `/api/events` — the sync endpoint. Serving a stale copy of the shared history would make the
 * two devices disagree while both believed they had synced, which is the exact failure the
 * whole event-log design (D-002) exists to prevent. It is better for a sync to fail loudly and
 * be retried than to succeed against a cache.
 */

const CACHE = 'lituk-v1';

self.addEventListener('install', (event) => {
  // The shell, so a cold start offline has something to open.
  event.waitUntil(caches.open(CACHE).then((cache) => cache.add('/')).catch(() => {}));
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith('/api/')) return; // see the note above

  // A navigation offline must open the app, not the browser's error page.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put('/', copy)).catch(() => {});
          return response;
        })
        .catch(() => caches.match('/').then((hit) => hit ?? Response.error())),
    );
    return;
  }

  // Everything else: answer from cache immediately if it is there, and refresh behind it, so
  // a returning reader never waits on the network for a chunk they already have.
  event.respondWith(
    caches.match(request).then((hit) => {
      const live = fetch(request)
        .then((response) => {
          if (response.ok) {
            const copy = response.clone();
            caches.open(CACHE).then((cache) => cache.put(request, copy)).catch(() => {});
          }
          return response;
        })
        .catch(() => hit ?? Response.error());
      return hit ?? live;
    }),
  );
});
